package com.tihai.utils;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import java.nio.file.*;import java.util.*;import java.nio.charset.StandardCharsets;import com.tihai.dubbo.pojo.course.Course;import static org.junit.jupiter.api.Assertions.*;
class SigninStoreTest {
 @TempDir Path temp;
 @Test void automationDefaultOffAndRecordsPersistWithoutDoubleClaim()throws Exception{SigninStore s=new SigninStore(temp);assertEquals(false,s.settings().get("autoNormal"));s.settings(true,Arrays.asList("fixture-course"));assertEquals(true,new SigninStore(temp).settings().get("autoNormal"));assertTrue(s.claim("fixture",Collections.singletonMap("title","Sample sign")));assertFalse(new SigninStore(temp).claim("fixture",Collections.emptyMap()));s.result("fixture","completed","平台确认");assertEquals("completed",new SigninStore(temp).record("fixture").get("state"));}
 @Test void validatesFiniteCoordinatesAndAxisOrder()throws Exception{SigninStore.validate(-90,180);assertThrows(java.io.IOException.class,()->SigninStore.validate(Double.NaN,0));assertThrows(java.io.IOException.class,()->SigninStore.validate(0,Double.POSITIVE_INFINITY));assertThrows(java.io.IOException.class,()->SigninStore.validate(104,30));assertThrows(java.io.IOException.class,()->SigninStore.validate(30,181));}
 @Test void gpxRoundTripKeepsChineseNamesAndWgs84Coordinates()throws Exception{SigninStore a=new SigninStore(temp.resolve("a"));a.addLocation("测试 & 位置",30.1234567,104.7654321,"备注 <一>");byte[] xml=a.exportGpx();SigninStore b=new SigninStore(temp.resolve("b"));assertEquals(1,b.importGpx(xml));assertEquals("测试 & 位置",b.locations().get(0).get("name"));assertEquals(30.1234567,((Number)b.locations().get(0).get("latitude")).doubleValue(),1e-9);assertEquals("WGS84",b.locations().get(0).get("coordinateSystem"));}
 @Test void externalEntitiesAndPartialInvalidImportsCannotChangeLocationBook()throws Exception{SigninStore s=new SigninStore(temp);String x="<!DOCTYPE gpx [<!ENTITY x SYSTEM 'file:///private'>]><gpx><wpt lat='1' lon='2'><name>&x;</name></wpt></gpx>";assertThrows(java.io.IOException.class,()->s.importGpx(x.getBytes(StandardCharsets.UTF_8)));String bad="<gpx><wpt lat='1' lon='2'/><wpt lat='999' lon='2'/></gpx>";assertThrows(java.io.IOException.class,()->s.importGpx(bad.getBytes(StandardCharsets.UTF_8)));assertTrue(s.locations().isEmpty());}
 @Test void activityTypesAndAmbiguousUserStatusDoNotImplySuccessfulAttendance()throws Exception{Course c=new Course();c.setCourseId("10");c.setClazzId("20");c.setTitle("Fixture course");String json="{\"result\":1,\"data\":{\"activeList\":[{\"id\":100,\"activeType\":2,\"otherId\":\"0\",\"userStatus\":1,\"status\":1},{\"id\":101,\"activeType\":2,\"otherId\":\"4\",\"status\":1},{\"id\":102,\"activeType\":2,\"otherId\":\"5\",\"status\":1}]}}";List<SigninCatalog.Entry> e=SigninCatalog.parse(json,"fixture",c,"30");assertEquals("normal",e.get(0).kind);assertEquals("location",e.get(1).kind);assertEquals("manual",e.get(2).kind);assertTrue(e.get(0).ongoing);assertEquals(e.get(0).id,SigninCatalog.parse(json,"fixture",c,"30").get(0).id);assertNotEquals(e.get(0).id,SigninCatalog.parse(json,"other-fixture",c,"30").get(0).id);}
 @Test void preflightMustMatchActivityAndNeverTreatPhoneRequirementAsOrdinary()throws Exception{SigninCatalog.Entry e=new SigninCatalog.Entry();e.activeId="100";e.courseId="10";e.clazzId="20";e.kind="normal";String html="<input id=activeId value=100><input id=courseId value=10><input id=classId value=20><input id=activeStatus value=1><script>function checkIfValidate(){};var target='/widget/sign/pcStuSignController/signIn';</script>";assertEquals("ready",SigninCatalog.inspect(html,e));assertThrows(java.io.IOException.class,()->SigninCatalog.inspect(html.replace("value=100","value=101"),e));assertEquals("phone_required",SigninCatalog.inspect("<p>此签到需要手机提供位置信息</p>",e));assertEquals("completed",SigninCatalog.inspect("<p>签到成功</p>",e));}
}
